import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":0}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><p>All notable changes to <code>pl.pojo:pojo-tester</code> are recorded here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>. Dates are the GitHub release dates.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/compare/0.7.6...master" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><p><code>0.8.0-SNAPSHOT</code>. Not a release. Published to the Central Portal snapshot repository after a green build on <code>master</code>.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>create(Class, Supplier)</code> builds a class the library cannot construct, including a builder.</li><li><code>quickly()</code> changes one field at a time. <code>thoroughly()</code> remains the default.</li><li><code>withFieldPrefix</code> matches <code>mName</code> and <code>m_name</code> to <code>getName</code>.</li><li><code>usingFluentAccessors()</code> accepts a getter or setter named after the field.</li><li><code>allowingSameHashCodeForUnequalObjects()</code> turns off the strict hash-code check.</li><li><code>changingFinalFields()</code> is the opt-in write of a <code>final</code> field. It is off by default.</li><li><code>toString</code> may quote a <code>String</code> or a <code>char</code>, and may print an <code>Object[]</code> with <code>Arrays.toString</code>.</li><li>Getters and setters are checked with a distinct value in every included field.</li><li><code>equals</code> is also checked with <code>null</code> in each included field that is not primitive and not <code>final</code>.</li><li>A package scan loads <code>*.class</code> files only.</li><li>GitHub Actions builds on Java 8, 11, 17, 21 and 25, and runs mutation tests, Spotless, SpotBugs and coverage.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The bytecode is still Java 8. Gradle 9 builds it and needs JDK 17 or newer.</li><li>A setter may return the class under test. A method that returns <code>Object</code> is not a setter.</li><li>JavaBeans names are kept when the second letter is uppercase (<code>getxCoordinate</code>, <code>getURL</code>).</li><li>An enum is not tested for setters. A setter of an enum-typed field on an ordinary class still is.</li><li>Publishing uses the Central Portal. Bintray and the old OSSRH host are not used. A release is signed and waits for the <code>release-ga</code> review. A snapshot waits for <code>release-snapshot</code>.</li><li>This site is built with VitePress from <code>docs/</code> and published to <code>gh-pages</code>.</li><li>Coverage reports use JaCoCo 0.8.16.</li><li>Tests no longer use PowerMock. Field access in tests goes through <code>helpers.Fields</code>.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Nested fields are given a new value when the nested class is included in the assertion.</li><li>A boxed numeric, <code>char</code> or <code>boolean</code> field that holds <code>null</code> is changed to a fixed non-null value instead of throwing <code>NullPointerException</code>.</li><li>A field typed as raw <code>java.lang.Enum</code> is set to <code>RoundingMode.UP</code>. <code>Enum(String, int)</code> is not called.</li><li>A non-public constructor whose only parameter is the class&#39;s own builder type is not called. A public constructor on that class still is.</li><li>Fields declared on a <code>java.*</code> superclass are not read. <code>Throwable.backtrace</code> is one of them.</li><li>A field whose second letter is uppercase also matches the accessor that capitalises the first letter (<code>tRow</code> / <code>getTRow</code>). <code>getxCoordinate</code> and <code>getURL</code> are unchanged.</li><li>A class with more than 12 fields, including a nested one, is checked with the linear strategy instead of every field combination. A warning names the class. Classes with 12 fields or fewer are unchanged.</li><li>Empty collections, maps and arrays can be told apart from <code>null</code>.</li><li>Static nested classes, field prefixes and the same hash code for unequal objects are covered by regression tests.</li><li><code>Class.newInstance()</code> is no longer used to construct a tester.</li></ul><h2 id="_0-7-6-—-2017-11-26" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.6" target="_blank" rel="noreferrer">0.7.6</a> — 2017-11-26 <a class="header-anchor" href="#_0-7-6-—-2017-11-26" aria-label="Permalink to “0.7.6 — 2017-11-26”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>quickly()</code>-style generation of fewer objects, then called quick testing (#201, #203).</li><li>More instantiators for JDK types (#192).</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A one-constant enum no longer throws an out-of-range exception (#199).</li><li>A getter that returns a defensive copy of an array is accepted (#212).</li></ul><h2 id="_0-7-5-—-2017-03-19" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.5" target="_blank" rel="noreferrer">0.7.5</a> — 2017-03-19 <a class="header-anchor" href="#_0-7-5-—-2017-03-19" aria-label="Permalink to “0.7.5 — 2017-03-19”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li>Field changers for the date and time types (#187).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>A custom <code>FieldValueChanger</code> no longer has to override <code>areDifferentValues</code> unless <code>Objects.equals</code> is the wrong comparison.</li></ul><h2 id="_0-7-4-—-2017-03-10" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.4" target="_blank" rel="noreferrer">0.7.4</a> — 2017-03-10 <a class="header-anchor" href="#_0-7-4-—-2017-03-10" aria-label="Permalink to “0.7.4 — 2017-03-10”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>BigInteger</code> and <code>BigDecimal</code> changers (#178).</li><li>Debug logging around a failed assertion (#179).</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The SLF4J dependency no longer collides with the test&#39;s binding (#184).</li></ul><h2 id="_0-7-3-—-2017-01-27" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.3" target="_blank" rel="noreferrer">0.7.3</a> — 2017-01-27 <a class="header-anchor" href="#_0-7-3-—-2017-01-27" aria-label="Permalink to “0.7.3 — 2017-01-27”">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Static fields are excluded (#170).</li><li>Unit tests and integration tests run as separate tasks (#160).</li></ul><h2 id="_0-7-2-—-2017-01-07" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.2" target="_blank" rel="noreferrer">0.7.2</a> — 2017-01-07 <a class="header-anchor" href="#_0-7-2-—-2017-01-07" aria-label="Permalink to “0.7.2 — 2017-01-07”">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to “Added”">​</a></h3><ul><li>An abstract class can be created without a default constructor (#157).</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Collection changers produce a non-empty collection (#153).</li></ul><h2 id="_0-7-1-—-2016-12-14" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.1" target="_blank" rel="noreferrer">0.7.1</a> — 2016-12-14 <a class="header-anchor" href="#_0-7-1-—-2016-12-14" aria-label="Permalink to “0.7.1 — 2016-12-14”">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>UUID</code> values are changed, and object generation no longer repeats a value that cannot be told apart (#149).</li></ul><h2 id="_0-7-0-—-2016-11-23" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.7.0" target="_blank" rel="noreferrer">0.7.0</a> — 2016-11-23 <a class="header-anchor" href="#_0-7-0-—-2016-11-23" aria-label="Permalink to “0.7.0 — 2016-11-23”">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to “Added”">​</a></h3><ul><li>Fields declared on a superclass are tested (#143).</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Equality uses the value, not the identity of a generated object (#146).</li></ul><h2 id="_0-6-0-—-2016-10-30" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.6.0" target="_blank" rel="noreferrer">0.6.0</a> — 2016-10-30 <a class="header-anchor" href="#_0-6-0-—-2016-10-30" aria-label="Permalink to “0.6.0 — 2016-10-30”">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>equals</code> and <code>hashCode</code> fail when they still depend on a field the test excluded (#121).</li></ul><h2 id="_0-5-0-—-2016-10-10" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.5.0" target="_blank" rel="noreferrer">0.5.0</a> — 2016-10-10 <a class="header-anchor" href="#_0-5-0-—-2016-10-10" aria-label="Permalink to “0.5.0 — 2016-10-10”">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to “Added”">​</a></h3><ul><li>Constructor tests (#113).</li><li><code>String</code> fields are changed by default (#133).</li><li>A package, or the package of a class, can be tested in one call (#114).</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Synthetic constructors are ignored (#126).</li></ul><h2 id="_0-4-0-—-2016-10-01" tabindex="-1"><a href="https://github.com/sta-szek/pojo-tester/releases/tag/0.4.0" target="_blank" rel="noreferrer">0.4.0</a> — 2016-10-01 <a class="header-anchor" href="#_0-4-0-—-2016-10-01" aria-label="Permalink to “0.4.0 — 2016-10-01”">​</a></h2><p>First open-source release.</p><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to “Added”">​</a></h3><ul><li>Javadoc.</li><li>Collections are instantiated instead of mocked (#112).</li></ul><h2 id="_0-3-0" tabindex="-1">[0.3.0] <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to “[0.3.0]”">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to “Added”">​</a></h3><ul><li>The public API checks its arguments (#66).</li><li>A class can be tested by name (#72).</li><li>The constructor and its arguments can be selected (#84).</li></ul><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Proxy classes are no longer generated for a type the library can construct (#88).</li></ul><h2 id="_0-2-0" tabindex="-1">[0.2.0] <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to “[0.2.0]”">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to “Added”">​</a></h3><ul><li>Getter and setter tests are separate (#87).</li><li>A new <code>String</code> is not empty (#86).</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A <code>boolean</code> field with an <code>is</code> getter finds its setter (#89).</li><li>A getter is not chosen because its name merely ends with the field name (#90).</li><li>Non-public classes and their accessors can be called (#75, #78).</li><li>Two generated instances are no longer the same object (#85).</li></ul><h2 id="_0-1-0" tabindex="-1">[0.1.0] <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to “[0.1.0]”">​</a></h2><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to “Added”">​</a></h3><ul><li>Tests for <code>equals</code>, <code>hashCode</code>, <code>toString</code>, getters and setters.</li><li>A class can be tested by name.</li></ul>`,66)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};